-- Production application data exported from Supabase project lnwvuwepwaexwybselsf.
-- Supabase-managed auth/session tables are intentionally excluded from version control.

truncate table public.player_step, public.game_state, public.game, public.desert restart identity cascade;





select setval(pg_get_serial_sequence('public.desert', 'id'), coalesce((select max(id) from public."desert"), 1), true);
select setval(pg_get_serial_sequence('public.game', 'id'), coalesce((select max(id) from public."game"), 1), true);
select setval(pg_get_serial_sequence('public.game_state', 'id'), coalesce((select max(id) from public."game_state"), 1), true);
select setval(pg_get_serial_sequence('public.player_step', 'id'), coalesce((select max(id) from public."player_step"), 1), true);
